age['id'] ?>"><label>Título<input name="page_title" maxlength="255" required value="<?= $e($page['title']) ?>"></label><label>Contenido HTML<textarea name="content" rows="8" maxlength="1048576"><?= $e($page['content']) ?></textarea></label><button class="nx-btn">Guardar en prueba</button></form><?php endif ?></details><?php endforeach ?>
